-- Pairing codes for browser extension device registration.
-- One-time codes generated by `personal-context-mcp pair-device`,
-- entered in the extension popup to authorize a browser.

CREATE TABLE IF NOT EXISTS pairing_codes (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code        TEXT NOT NULL UNIQUE,
    device_name TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at  TIMESTAMPTZ NOT NULL DEFAULT (now() + interval '5 minutes'),
    used_at     TIMESTAMPTZ,
    used_by_device_id TEXT
);

CREATE INDEX IF NOT EXISTS pairing_codes_code_idx ON pairing_codes (code) WHERE used_at IS NULL;